import{l as a,a as i,c as o,a6 as r}from"./chunks/framework.CVVsdWKy.js";const p=JSON.parse('{"title":"ai-memory","description":"","frontmatter":{},"headers":[],"relativePath":"ai/cli/ai-memory.md","filePath":"ai/cli/ai-memory.md"}'),t={name:"ai/cli/ai-memory.md"};function l(m,e,n,c,d,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-memory" tabindex="-1">ai-memory <a class="header-anchor" href="#ai-memory" aria-label="Permalink to &quot;ai-memory&quot;">​</a></h1><h2 id="why" tabindex="-1">why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;why&quot;">​</a></h2><p>Agent 如果有记忆，可以快速想起上次没干完的任务、任务关联的关键代码位置、历史执行中遇到的坑、用户偏好等信息，更加找到要修改的位置、按照期望的执行。</p><p>但是记忆也会有一些问题：</p><ol><li>会话中的临时想法，被当成了偏好</li><li>记忆过期，与实际代码有偏差</li><li>记忆难以共享，同代码仓跨 worktree 就难以共享</li><li>记忆的创建、更新、后台维护消耗 token 非常多</li></ol><p>但是 ai-memory 的记忆维护不需要使用 token，而且是固定 md + 自动生成数据库方案，实现可随意查看修改，又能快速检索使用，且支持很多不同的 Agent 共享记忆。</p><h2 id="how" tabindex="-1">how <a class="header-anchor" href="#how" aria-label="Permalink to &quot;how&quot;">​</a></h2><p>以在 pi agent 中使用为例：</p><ol><li>安装 <a href="https://github.com/akitaonrails/ai-memory" target="_blank" rel="noreferrer">ai-memory</a>，并添加到 PATH 环境变量，使得程序全局可方案</li><li>初始化 <code>ai-memory setup --yes --agent pi</code>，会添加 pi 插件和 pi MCP</li><li>随 pi 启动自动运行，会话启动自动拿到 handoff，会话中自动记忆、自动检索，会话结束，后台 ai-memory 服务可添加 LLM 整合（生成 wiki 页，更新 handoff 快照等）</li><li>检查服务状态：pi 中 <code>/mcp</code> 中连接正常，终端 <code>ai-memory status</code> 正常</li><li>记忆共享，给其他 agent 也接入 <code>ai-memory run claude</code>，自动安装 hooks + MCP</li></ol>',9)])])}const y=a(t,[["render",l]]);export{p as __pageData,y as default};
